-- Completes and verifies the four official BNCC high-school area catalogs.
-- Texts and source locators are from bncc.dev/bncc-dados, sourced from the MEC
-- workbook BNCC_Ensino_Medio.xlsx and homologated BNCC PDF. The upstream data
-- is CC BY 4.0; provenance and source metadata are retained per skill.
-- Existing skill primary keys are preserved so question/history links survive.

-- Restore official area competencies before inserting skill links. Existing
-- competency IDs are retained by upserting on area and official number.
WITH official_competencies(area_key, number, source_key, description, source_metadata) AS (
VALUES
  ('em-area-lgg', 1, 'em-area-lgg-ce-01', 'Compreender o funcionamento das diferentes linguagens e práticas culturais (artísticas, corporais e verbais) e mobilizar esses conhecimentos na recepção e produção de discursos nos diferentes campos de atuação social e nas diversas mídias, para ampliar as formas de participação social, o entendimento e as possibilidades de explicação e interpretação crítica da realidade e para continuar aprendendo.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Linguagens e suas Tec","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 492","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-lgg', 2, 'em-area-lgg-ce-02', 'Compreender os processos identitários, conflitos e relações de poder que permeiam as práticas sociais de linguagem, respeitando as diversidades e a pluralidade de ideias e posições, e atuar socialmente com base em princípios e valores assentados na democracia, na igualdade e nos Direitos Humanos, exercitando o autoconhecimento, a empatia, o diálogo, a resolução de conflitos e a cooperação, e combatendo preconceitos de qualquer natureza.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Linguagens e suas Tec","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 492","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-lgg', 3, 'em-area-lgg-ce-03', 'Utilizar diferentes linguagens (artísticas, corporais e verbais) para exercer, com autonomia e colaboração, protagonismo e autoria na vida pessoal e coletiva, de forma crítica, criativa, ética e solidária, defendendo pontos de vista que respeitem o outro e promovam os Direitos Humanos, a consciência socioambiental e o consumo responsável, em âmbito local, regional e global.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Linguagens e suas Tec","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 492","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-lgg', 4, 'em-area-lgg-ce-04', 'Compreender as línguas como fenômeno (geo)político, histórico, cultural, social, variável, heterogêneo e sensível aos contextos de uso, reconhecendo suas variedades e vivenciando-as como formas de expressões identitárias, pessoais e coletivas, bem como agindo no enfrentamento de preconceitos de qualquer natureza.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Linguagens e suas Tec","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 492","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-lgg', 5, 'em-area-lgg-ce-05', 'Compreender os processos de produção e negociação de sentidos nas práticas corporais, reconhecendo-as e vivenciando-as como formas de expressão de valores e identidades, em uma perspectiva democrática e de respeito à diversidade.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Linguagens e suas Tec","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 492","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-lgg', 6, 'em-area-lgg-ce-06', 'Apreciar esteticamente as mais diversas produções artísticas e culturais, considerando suas características locais, regionais e globais, e mobilizar seus conhecimentos sobre as linguagens artísticas para dar significado e (re)construir produções autorais individuais e coletivas, exercendo protagonismo de maneira crítica e criativa, com respeito à diversidade de saberes, identidades e culturas.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Linguagens e suas Tec","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 492","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-lgg', 7, 'em-area-lgg-ce-07', 'Mobilizar práticas de linguagem no universo digital, considerando as dimensões técnicas, críticas, criativas, éticas e estéticas, para expandir as formas de produzir sentidos, de engajar-se em práticas autorais e coletivas, e de aprender a aprender nos campos da ciência, cultura, trabalho, informação e vida pessoal e coletiva.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Linguagens e suas Tec","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 492","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-mat', 1, 'em-area-mat-ce-01', 'Utilizar estratégias, conceitos e procedimentos matemáticos para interpretar situações em diversos contextos, sejam atividades cotidianas, sejam fatos das Ciências da Natureza e Humanas, das questões socioeconômicas ou tecnológicas, divulgados por diferentes meios, de modo a contribuir para uma formação geral.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Matemática e suas Te","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 533","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-mat', 2, 'em-area-mat-ce-02', 'Propor ou participar de ações para investigar desafios do mundo contemporâneo e tomar decisões éticas e socialmente responsáveis, com base na análise de problemas sociais, como os voltados a situações de saúde, sustentabilidade, das implicações da tecnologia no mundo do trabalho, entre outros, mobilizando e articulando conceitos, procedimentos e linguagens próprios da Matemática.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Matemática e suas Te","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 533","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-mat', 3, 'em-area-mat-ce-03', 'Utilizar estratégias, conceitos, definições e procedimentos matemáticos para interpretar, construir modelos e resolver problemas em diversos contextos, analisando a plausibilidade dos resultados e a adequação das soluções propostas, de modo a construir argumentação consistente.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Matemática e suas Te","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 533","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-mat', 4, 'em-area-mat-ce-04', 'Compreender e utilizar, com flexibilidade e precisão, diferentes registros de representação matemáticos (algébrico, geométrico, estatístico, computacional etc.), na busca de solução e comunicação de resultados de problemas.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Matemática e suas Te","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 533","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-mat', 5, 'em-area-mat-ce-05', 'Investigar e estabelecer conjecturas a respeito de diferentes conceitos e propriedades matemáticas, empregando estratégias e recursos, como observação de padrões, experimentações e diferentes tecnologias, identificando a necessidade, ou não, de uma demonstração cada vez mais formal na validação das referidas conjecturas.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Matemática e suas Te","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 533","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-cnt', 1, 'em-area-cnt-ce-01', 'Analisar fenômenos naturais e processos tecnológicos, com base nas interações e relações entre matéria e energia, para propor ações individuais e coletivas que aperfeiçoem processos produtivos, minimizem impactos socioambientais e melhorem as condições de vida em âmbito local, regional e global.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Ciências da Natureza","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 555","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-cnt', 2, 'em-area-cnt-ce-02', 'Analisar e utilizar interpretações sobre a dinâmica da Vida, da Terra e do Cosmos para elaborar argumentos, realizar previsões sobre o funcionamento e a evolução dos seres vivos e do Universo, e fundamentar e defender decisões éticas e responsáveis.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Ciências da Natureza","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 555","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-cnt', 3, 'em-area-cnt-ce-03', 'Investigar situações-problema e avaliar aplicações do conhecimento científico e tecnológico e suas implicações no mundo, utilizando procedimentos e linguagens próprios das Ciências da Natureza, para propor soluções que considerem demandas locais, regionais e/ou globais, e comunicar suas descobertas e conclusões a públicos variados, em diversos contextos e por meio de diferentes mídias e tecnologias digitais de informação e comunicação (TDIC).', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Ciências da Natureza","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 555","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-chs', 1, 'em-area-chs-ce-01', 'Analisar processos políticos, econômicos, sociais, ambientais e culturais nos âmbitos local, regional, nacional e mundial em diferentes tempos, a partir da pluralidade de procedimentos epistemológicos, científicos e tecnológicos, de modo a compreender e posicionar-se criticamente em relação a eles, considerando diferentes pontos de vista e tomando decisões baseadas em argumentos e fontes de natureza científica.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Ciências Humanas e S","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 572","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-chs', 2, 'em-area-chs-ce-02', 'Analisar a formação de territórios e fronteiras em diferentes tempos e espaços, mediante a compreensão das relações de poder que determinam as territorialidades e o papel geopolítico dos Estados-nações.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Ciências Humanas e S","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 572","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-chs', 3, 'em-area-chs-ce-03', 'Analisar e avaliar criticamente as relações de diferentes grupos, povos e sociedades com a natureza (produção, distribuição e consumo) e seus impactos econômicos e socioambientais, com vistas à proposição de alternativas que respeitem e promovam a consciência, a ética socioambiental e o consumo responsável em âmbito local, regional, nacional e global.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Ciências Humanas e S","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 572","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-chs', 4, 'em-area-chs-ce-04', 'Analisar as relações de produção, capital e trabalho em diferentes territórios, contextos e culturas, discutindo o papel dessas relações na construção, consolidação e transformação das sociedades.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Ciências Humanas e S","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 572","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-chs', 5, 'em-area-chs-ce-05', 'Identificar e combater as diversas formas de injustiça, preconceito e violência, adotando princípios éticos, democráticos, inclusivos e solidários, e respeitando os Direitos Humanos.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Ciências Humanas e S","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 572","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb),
  ('em-area-chs', 6, 'em-area-chs-ce-06', 'Participar do debate público de forma crítica, respeitando diferentes posições e fazendo escolhas alinhadas ao exercício da cidadania e ao seu projeto de vida, com liberdade, autonomia, consciência crítica e responsabilidade.', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comp. de Ciências Humanas e S","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 572","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb)
)
INSERT INTO curriculum_competencies (area_id, source_key, number, description, source_metadata)
SELECT area.id, official.source_key, official.number, official.description, official.source_metadata
FROM official_competencies official
JOIN curriculum_areas area
  ON area.curriculum_version = 'BNCC-2018'
 AND area.source_key = official.area_key
ON CONFLICT (area_id, number) DO UPDATE
SET source_key = EXCLUDED.source_key,
    description = EXCLUDED.description,
    source_metadata = EXCLUDED.source_metadata;

WITH official_skills(code, description, area_key, source_metadata, subject) AS (
VALUES
  ('EM13CHS101', 'Identificar, analisar e comparar diferentes fontes e narrativas expressas em diversas linguagens, com vistas à compreensão de ideias filosóficas e de processos e eventos históricos, geográficos, políticos, econômicos, sociais, ambientais e culturais.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 3","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 574","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS102', 'Identificar, analisar e discutir as circunstâncias históricas, geográficas, políticas, econômicas, sociais, ambientais e culturais de matrizes conceituais (etnocentrismo, racismo, evolução, modernidade, cooperativismo/desenvolvimento etc.), avaliando criticamente seu significado histórico e comparando-as a narrativas que contemplem outros agentes e discursos.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 4","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 574","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS103', 'Elaborar hipóteses, selecionar evidências e compor argumentos relativos a processos políticos, econômicos, sociais, ambientais, culturais e epistemológicos, com base na sistematização de dados e informações de diversas naturezas (expressões artísticas, textos filosóficos e sociológicos, documentos históricos e geográficos, gráficos, mapas, tabelas, tradições orais, entre outros).', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 5","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 574","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS104', 'Analisar objetos e vestígios da cultura material e imaterial de modo a identificar conhecimentos, valores, crenças e práticas que caracterizam a identidade e a diversidade cultural de diferentes sociedades inseridas no tempo e no espaço.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 6","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 574","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS105', 'Identificar, contextualizar e criticar tipologias evolutivas (populações nômades e sedentárias, entre outras) e oposições dicotômicas (cidade/campo, cultura/ natureza, civilizados/bárbaros, razão/emoção, material/virtual etc.), explicitando suas ambiguidades.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 7","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 574","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS106', 'Utilizar as linguagens cartográfica, gráfica e iconográfica, diferentes gêneros textuais e tecnologias digitais de informação e comunicação de forma crítica, significativa, reflexiva e ética nas diversas práticas sociais, incluindo as escolares, para se comunicar, acessar e difundir informações, produzir conhecimentos, resolver problemas e exercer protagonismo e autoria na vida pessoal e coletiva.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 8","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 574","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS201', 'Analisar e caracterizar as dinâmicas das populações, das mercadorias e do capital nos diversos continentes, com destaque para a mobilidade e a fixação de pessoas, grupos humanos e povos, em função de eventos naturais, políticos, econômicos, sociais, religiosos e culturais, de modo a compreender e posicionar-se criticamente em relação a esses processos e às possíveis relações entre eles.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 9","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 575","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS202', 'Analisar e avaliar os impactos das tecnologias na estruturação e nas dinâmicas de grupos, povos e sociedades contemporâneos (fluxos populacionais, financeiros, de mercadorias, de informações, de valores éticos e culturais etc.), bem como suas interferências nas decisões políticas, sociais, ambientais, econômicas e culturais.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 10","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 575","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS203', 'Comparar os significados de território, fronteiras e vazio (espacial, temporal e cultural) em diferentes sociedades, contextualizando e relativizando visões dualistas (civilização/barbárie, nomadismo/sedentarismo, esclarecimento/obscurantismo, cidade/campo, entre outras).', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 11","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 575","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS204', 'Comparar e avaliar os processos de ocupação do espaço e a formação de territórios, territorialidades e fronteiras, identificando o papel de diferentes agentes (como grupos sociais e culturais, impérios, Estados Nacionais e organismos internacionais) e considerando os conflitos populacionais (internos e externos), a diversidade étnico-cultural e as características socioeconômicas, políticas e tecnológicas.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 12","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 575","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS205', 'Analisar a produção de diferentes territorialidades em suas dimensões culturais, econômicas, ambientais, políticas e sociais, no Brasil e no mundo contemporâneo, com destaque para as culturas juvenis.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 13","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 575","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS206', 'Analisar a ocupação humana e a produção do espaço em diferentes tempos, aplicando os princípios de localização, distribuição, ordem, extensão, conexão, arranjos, casualidade, entre outros que contribuem para o raciocínio geográfico.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 14","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 575","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS301', 'Problematizar hábitos e práticas individuais e coletivos de produção, reaproveitamento e descarte de resíduos em metrópoles, áreas urbanas e rurais, e comunidades com diferentes características socioeconômicas, e elaborar e/ou selecionar propostas de ação que promovam a sustentabilidade socioambiental, o combate à poluição sistêmica e o consumo responsável.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 15","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 577","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS302', 'Analisar e avaliar criticamente os impactos econômicos e socioambientais de cadeias produtivas ligadas à exploração de recursos naturais e às atividades agropecuárias em diferentes ambientes e escalas de análise, considerando o modo de vida das populações locais - entre elas as indígenas, quilombolas e demais comunidades tradicionais -, suas práticas agroextrativistas e o compromisso com a sustentabilidade.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 16","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 577","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS303', 'Debater e avaliar o papel da indústria cultural e das culturas de massa no estímulo ao consumismo, seus impactos econômicos e socioambientais, com vistas à percepção crítica das necessidades criadas pelo consumo e à adoção de hábitos sustentáveis.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 17","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 577","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS304', 'Analisar os impactos socioambientais decorrentes de práticas de instituições governamentais, de empresas e de indivíduos, discutindo as origens dessas práticas, selecionando, incorporando e promovendo aquelas que favoreçam a consciência e a ética socioambiental e o consumo responsável.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 18","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 577","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS305', 'Analisar e discutir o papel e as competências legais dos organismos nacionais e internacionais de regulação, controle e fiscalização ambiental e dos acordos internacionais para a promoção e a garantia de práticas ambientais sustentáveis.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 19","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 577","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS306', 'Contextualizar, comparar e avaliar os impactos de diferentes modelos socioeconômicos no uso dos recursos naturais e na promoção da sustentabilidade econômica e socioambiental do planeta (como a adoção dos sistemas da agrobiodiversidade e agroflorestal por diferentes comunidades, entre outros).', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 20","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 577","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS401', 'Identificar e analisar as relações entre sujeitos, grupos, classes sociais e sociedades com culturas distintas diante das transformações técnicas, tecnológicas e informacionais e das novas formas de trabalho ao longo do tempo, em diferentes espaços (urbanos e rurais) e contextos.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 21","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 578","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS402', 'Analisar e comparar indicadores de emprego, trabalho e renda em diferentes espaços, escalas e tempos, associando-os a processos de estratificação e desigualdade socioeconômica.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 22","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 578","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS403', 'Caracterizar e analisar os impactos das transformações tecnológicas nas relações sociais e de trabalho próprias da contemporaneidade, promovendo ações voltadas à superação das desigualdades sociais, da opressão e da violação dos Direitos Humanos.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 23","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 578","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS404', 'Identificar e discutir os múltiplos aspectos do trabalho em diferentes circunstâncias e contextos históricos e/ou geográficos e seus efeitos sobre as gerações, em especial, os jovens, levando em consideração, na atualidade, as transformações técnicas, tecnológicas e informacionais.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 24","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 578","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS501', 'Analisar os fundamentos da ética em diferentes culturas, tempos e espaços, identificando processos que contribuem para a formação de sujeitos éticos que valorizem a liberdade, a cooperação, a autonomia, o empreendedorismo, a convivência democrática e a solidariedade.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 25","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 579","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS502', 'Analisar situações da vida cotidiana, estilos de vida, valores, condutas etc., desnaturalizando e problematizando formas de desigualdade, preconceito, intolerância e discriminação, e identificar ações que promovam os Direitos Humanos, a solidariedade e o respeito às diferenças e às liberdades individuais.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 26","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 579","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS503', 'Identificar diversas formas de violência (física, simbólica, psicológica etc.), suas principais vítimas, suas causas sociais, psicológicas e afetivas, seus significados e usos políticos, sociais e culturais, discutindo e avaliando mecanismos para combatê-las, com base em argumentos éticos.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 27","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 579","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS504', 'Analisar e avaliar os impasses ético-políticos decorrentes das transformações culturais, sociais, históricas, científicas e tecnológicas no mundo contemporâneo e seus desdobramentos nas atitudes e nos valores de indivíduos, grupos sociais, sociedades e culturas.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 28","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 579","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS601', 'Identificar e analisar as demandas e os protagonismos políticos, sociais e culturais dos povos indígenas e das populações afrodescendentes (incluindo as quilombolas) no Brasil contemporâneo considerando a história das Américas e o contexto de exclusão e inclusão precária desses grupos na ordem social e econômica atual, promovendo ações para a redução das desigualdades étnico-raciais no país.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 29","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 581","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS602', 'Identificar e caracterizar a presença do paternalismo, do autoritarismo e do populismo na política, na sociedade e nas culturas brasileira e latino-americana, em períodos ditatoriais e democráticos, relacionando-os com as formas de organização e de articulação das sociedades em defesa da autonomia, da liberdade, do diálogo e da promoção da democracia, da cidadania e dos direitos humanos na sociedade atual.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 30","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 581","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS603', 'Analisar a formação de diferentes países, povos e nações e de suas experiências políticas e de exercício da cidadania, aplicando conceitos políticos básicos (Estado, poder, formas, sistemas e regimes de governo, soberania etc.).', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 31","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 581","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS604', 'Discutir o papel dos organismos internacionais no contexto mundial, com vistas à elaboração de uma visão crítica sobre seus limites e suas formas de atuação nos países, considerando os aspectos positivos e negativos dessa atuação para as populações locais.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 32","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 581","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS605', 'Analisar os princípios da declaração dos Direitos Humanos, recorrendo às noções de justiça, igualdade e fraternidade, identificar os progressos e entraves à concretização desses direitos nas diversas sociedades contemporâneas e promover ações concretas diante da desigualdade e das violações desses direitos em diferentes espaços de vivência, respeitando a identidade de cada grupo e de cada indivíduo.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências Humanas e So'', linha 33","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 581","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CHS606', 'Analisar as características socioeconômicas da sociedade brasileira - com base na análise de documentos (dados, tabelas, mapas etc.) de diferentes fontes - e propor medidas para enfrentar os problemas identificados e construir uma sociedade mais próspera, justa e inclusiva, que valorize o protagonismo de seus cidadãos e promova o autoconhecimento, a autoestima, a autoconfiança e a empatia.', 'em-area-chs', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 3","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 581","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências Humanas e Sociais Aplicadas'),
  ('EM13CNT101', 'Analisar e representar, com ou sem o uso de dispositivos e de aplicativos digitais específicos, as transformações e conservações em sistemas que envolvam quantidade de matéria, de energia e de movimento para realizar previsões sobre seus comportamentos em situações cotidianas e em processos produtivos que priorizem o desenvolvimento sustentável, o uso consciente dos recursos naturais e a preservação da vida em todas as suas formas.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 4","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 557","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT102', 'Realizar previsões, avaliar intervenções e/ou construir protótipos de sistemas térmicos que visem à sustentabilidade, considerando sua composição e os efeitos das variáveis termodinâmicas sobre seu funcionamento, considerando também o uso de tecnologias digitais que auxiliem no cálculo de estimativas e no apoio à construção dos protótipos.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 5","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 557","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT103', 'Utilizar o conhecimento sobre as radiações e suas origens para avaliar as potencialidades e os riscos de sua aplicação em equipamentos de uso cotidiano, na saúde, no ambiente, na indústria, na agricultura e na geração de energia elétrica.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 6","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 557","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT104', 'Avaliar os benefícios e os riscos à saúde e ao ambiente, considerando a composição, a toxicidade e a reatividade de diferentes materiais e produtos, como também o nível de exposição a eles, posicionando-se criticamente e propondo soluções individuais e/ou coletivas para seus usos e descartes responsáveis.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 7","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 557","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT105', 'Analisar os ciclos biogeoquímicos e interpretar os efeitos de fenômenos naturais e da interferência humana sobre esses ciclos, para promover ações individuais e/ ou coletivas que minimizem consequências nocivas à vida.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 8","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 557","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT106', 'Avaliar, com ou sem o uso de dispositivos e aplicativos digitais, tecnologias e possíveis soluções para as demandas que envolvem a geração, o transporte, a distribuição e o consumo de energia elétrica, considerando a disponibilidade de recursos, a eficiência energética, a relação custo/benefício, as características geográficas e ambientais, a produção de resíduos e os impactos socioambientais e culturais.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 9","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 557","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT107', 'Realizar previsões qualitativas e quantitativas sobre o funcionamento de geradores, motores elétricos e seus componentes, bobinas, transformadores, pilhas, baterias e dispositivos eletrônicos, com base na análise dos processos de transformação e condução de energia envolvidos - com ou sem o uso de dispositivos e aplicativos digitais -, para propor ações que visem a sustentabilidade.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 10","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 557","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT201', 'Analisar e discutir modelos, teorias e leis propostos em diferentes épocas e culturas para comparar distintas explicações sobre o surgimento e a evolução da Vida, da Terra e do Universo com as teorias científicas aceitas atualmente.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 11","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT202', 'Analisar as diversas formas de manifestação da vida em seus diferentes níveis de organização, bem como as condições ambientais favoráveis e os fatores limitantes a elas, com ou sem o uso de dispositivos e aplicativos digitais (como softwares de simulação e de realidade virtual, entre outros).', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 12","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT203', 'Avaliar e prever efeitos de intervenções nos ecossistemas, e seus impactos nos seres vivos e no corpo humano, com base nos mecanismos de manutenção da vida, nos ciclos da matéria e nas transformações e transferências de energia, utilizando representações e simulações sobre tais fatores, com ou sem o uso de dispositivos e aplicativos digitais (como softwares de simulação e de realidade virtual, entre outros).', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 13","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT204', 'Elaborar explicações, previsões e cálculos a respeito dos movimentos de objetos na Terra, no Sistema Solar e no Universo com base na análise das interações gravitacionais, com ou sem o uso de dispositivos e aplicativos digitais (como softwares de simulação e de realidade virtual, entre outros).', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 14","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT205', 'Interpretar resultados e realizar previsões sobre atividades experimentais, fenômenos naturais e processos tecnológicos, com base nas noções de probabilidade e incerteza, reconhecendo os limites explicativos das ciências.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 15","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT206', 'Discutir a importância da preservação e conservação da biodiversidade, considerando parâmetros qualitativos e quantitativos, e avaliar os efeitos da ação humana e das políticas ambientais para a garantia da sustentabilidade do planeta.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 16","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT207', 'Identificar, analisar e discutir vulnerabilidades vinculadas às vivências e aos desafios contemporâneos aos quais as juventudes estão expostas, considerando os aspectos físico, psicoemocional e social, a fim de desenvolver e divulgar ações de prevenção e de promoção da saúde e do bem-estar.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 17","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT208', 'Aplicar os princípios da evolução biológica para analisar a história humana, considerando sua origem, diversificação, dispersão pelo planeta e diferentes formas de interação com a natureza, valorizando e respeitando a diversidade étnica e cultural humana.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 18","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT209', 'Analisar a evolução estelar associando-a aos modelos de origem e distribuição dos elementos químicos no Universo, compreendendo suas relações com as condições necessárias ao surgimento de sistemas solares e planetários, suas estruturas e composições e as possibilidades de existência de vida, utilizando representações e simulações, com ou sem o uso de dispositivos e aplicativos digitais (como softwares de simulação e de realidade virtual, entre outros).', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 19","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT301', 'Construir questões, elaborar hipóteses, previsões e estimativas, empregar instrumentos de medição e representar e interpretar modelos explicativos, dados e/ou resultados experimentais para construir, avaliar e justificar conclusões no enfrentamento de situações-problema sob uma perspectiva científica.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 20","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 561","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT302', 'Comunicar, para públicos variados, em diversos contextos, resultados de análises, pesquisas e/ou experimentos, elaborando e/ou interpretando textos, gráficos, tabelas, símbolos, códigos, sistemas de classificação e equações, por meio de diferentes linguagens, mídias, tecnologias digitais de informação e comunicação (TDIC), de modo a participar e/ou promover debates em torno de temas científicos e/ou tecnológicos de relevância sociocultural e ambiental.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 21","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 561","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT303', 'Interpretar textos de divulgação científica que tratem de temáticas das Ciências da Natureza, disponíveis em diferentes mídias, considerando a apresentação dos dados, tanto na forma de textos como em equações, gráficos e/ou tabelas, a consistência dos argumentos e a coerência das conclusões, visando construir estratégias de seleção de fontes confiáveis de informações.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 22","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 561","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT304', 'Analisar e debater situações controversas sobre a aplicação de conhecimentos da área de Ciências da Natureza (tais como tecnologias do DNA, tratamentos com células-tronco, neurotecnologias, produção de tecnologias de defesa, estratégias de controle de pragas, entre outros), com base em argumentos consistentes, legais, éticos e responsáveis, distinguindo diferentes pontos de vista.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 23","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 561","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT305', 'Investigar e discutir o uso indevido de conhecimentos das Ciências da Natureza na justificativa de processos de discriminação, segregação e privação de direitos individuais e coletivos, em diferentes contextos sociais e históricos, para promover a equidade e o respeito à diversidade.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 24","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 561","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT306', 'Avaliar os riscos envolvidos em atividades cotidianas, aplicando conhecimentos das Ciências da Natureza, para justificar o uso de equipamentos e recursos, bem como comportamentos de segurança, visando à integridade física, individual e coletiva, e socioambiental, podendo fazer uso de dispositivos e aplicativos digitais que viabilizem a estruturação de simulações de tais riscos.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 25","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 561","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT307', 'Analisar as propriedades dos materiais para avaliar a adequação de seu uso em diferentes aplicações (industriais, cotidianas, arquitetônicas ou tecnológicas) e/ ou propor soluções seguras e sustentáveis considerando seu contexto local e cotidiano.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 26","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 561","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT308', 'Investigar e analisar o funcionamento de equipamentos elétricos e/ou eletrônicos e sistemas de automação para compreender as tecnologias contemporâneas e avaliar seus impactos sociais, culturais e ambientais.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 27","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 562","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT309', 'Analisar questões socioambientais, políticas e econômicas relativas à dependência do mundo atual em relação aos recursos não renováveis e discutir a necessidade de introdução de alternativas e novas tecnologias energéticas e de materiais, comparando diferentes tipos de motores e processos de produção de novos materiais.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 28","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 562","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
  ('EM13CNT310', 'Investigar e analisar os efeitos de programas de infraestrutura e demais serviços básicos (saneamento, energia elétrica, transporte, telecomunicações, cobertura vacinal, atendimento primário à saúde e produção de alimentos, entre outros) e identificar necessidades locais e/ou regionais em relação a esses serviços, a fim de avaliar e/ou promover ações que contribuam para a melhoria na qualidade de vida e nas condições de saúde da população.', 'em-area-cnt', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Linguagens e suas Tecn'', linha 3","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 562","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Ciências da Natureza e suas Tecnologias'),
