  ('EM13MAT202', 'Planejar e executar pesquisa amostral sobre questões relevantes, usando dados coletados diretamente ou em diferentes fontes, e comunicar os resultados por meio de relatório contendo gráficos e interpretação das medidas de tendência central e das medidas de dispersão (amplitude e desvio padrão), utilizando ou não recursos tecnológicos.', 'em-area-mat', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Matemática e suas Tec'', linha 10","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 536","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Matemática e suas Tecnologias'),
