  ('EM13MAT402', 'Converter representações algébricas de funções polinomiais de 2º grau em representações geométricas no plano cartesiano, distinguindo os casos nos quais uma variável for diretamente proporcional ao quadrado da outra, recorrendo ou não a softwares ou aplicativos de álgebra e geometria dinâmica, entre outros materiais.', 'em-area-mat', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Matemática e suas Tec'', linha 29","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 541","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Matemática e suas Tecnologias'),
