  ('EM13MAT504', 'Investigar processos de obtenção da medida do volume de prismas, pirâmides, cilindros e cones, incluindo o princípio de Cavalieri, para a obtenção das fórmulas de cálculo da medida do volume dessas figuras.', 'em-area-mat', '{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Matemática e suas Tec'', linha 38","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 543","proveniencia_catalogo":"bncc.dev/bncc-dados","commit_catalogo":"9c268978efa2aa250834c6a9edb6074432752838"}'::jsonb, 'Matemática e suas Tecnologias'),
