INSERT INTO curriculum_skills
  (curriculum_version, code, stage, subject, grade_range, description,
   dataset_version, validity_status, source_metadata)
SELECT 'BNCC-2018', code, 'Ensino Médio', subject,
       'Ensino Médio (sem seriação)', description, 'dados-2026.07',
       'vigente', source_metadata
FROM official_skills
ON CONFLICT (curriculum_version, code) DO UPDATE
SET stage = EXCLUDED.stage,
    subject = EXCLUDED.subject,
    grade_range = EXCLUDED.grade_range,
    description = EXCLUDED.description,
    knowledge_object_id = NULL,
    dataset_version = EXCLUDED.dataset_version,
    validity_status = EXCLUDED.validity_status,
    source_metadata = EXCLUDED.source_metadata;

-- Area skills are associated with the corresponding competency number encoded
-- in their official code (for example EM13CHS101 -> competency 1).
DELETE FROM skill_competencies link
USING curriculum_skills skill
WHERE link.skill_id = skill.id
  AND skill.curriculum_version = 'BNCC-2018'
  AND skill.code ~ '^EM13(CHS|LGG|MAT|CNT)[0-9]{3}$';

INSERT INTO skill_competencies (skill_id, competency_id)
SELECT skill.id, competency.id
FROM curriculum_skills skill
JOIN curriculum_areas area
  ON area.curriculum_version = skill.curriculum_version
 AND area.source_key = CASE
   WHEN skill.code LIKE 'EM13CHS%' THEN 'em-area-chs'
   WHEN skill.code LIKE 'EM13LGG%' THEN 'em-area-lgg'
   WHEN skill.code LIKE 'EM13MAT%' THEN 'em-area-mat'
   WHEN skill.code LIKE 'EM13CNT%' THEN 'em-area-cnt'
 END
JOIN curriculum_competencies competency
  ON competency.area_id = area.id
 AND competency.number = substring(skill.code FROM 8 FOR 1)::integer
WHERE skill.curriculum_version = 'BNCC-2018'
  AND skill.stage = 'Ensino Médio'
  AND skill.code ~ '^EM13(CHS|LGG|MAT|CNT)[0-9]{3}$';

-- Restore the area-to-discipline links used by the frontend. The individual
-- component skills remain scoped to their specific discipline in migration 093.
INSERT INTO pedagogical_discipline_skills
  (discipline_id, skill_id, tagged_by, rationale)
SELECT discipline.id, skill.id, discipline.created_by,
       'Habilidade BNCC associada à área curricular oficial do Ensino Médio.'
FROM pedagogical_disciplines discipline
JOIN curriculum_areas area ON area.id = discipline.area_id
JOIN curriculum_skills skill
  ON skill.curriculum_version = 'BNCC-2018'
 AND skill.stage = 'Ensino Médio'
 AND ((area.source_key = 'em-area-chs' AND skill.code LIKE 'EM13CHS%')
   OR (area.source_key = 'em-area-lgg' AND skill.code LIKE 'EM13LGG%')
   OR (area.source_key = 'em-area-mat' AND skill.code LIKE 'EM13MAT%')
   OR (area.source_key = 'em-area-cnt' AND skill.code LIKE 'EM13CNT%'))
WHERE discipline.stage = 'Ensino Médio'
ON CONFLICT (discipline_id, skill_id) DO NOTHING;

DO $$
DECLARE total_skills integer; area_skills integer;
        competency_links integer; missing_competency_links integer;
BEGIN
  SELECT count(*) INTO total_skills FROM curriculum_skills
  WHERE curriculum_version = 'BNCC-2018' AND stage = 'Ensino Médio'
    AND (code ~ '^EM13(CHS|LGG|MAT|CNT)[0-9]{3}$' OR code ~ '^EM13LP[0-9]{2}$');
  IF total_skills <> 183 THEN
    RAISE EXCEPTION 'Catálogo BNCC do Ensino Médio incompleto: esperadas 183 habilidades, encontradas %.', total_skills;
  END IF;

  SELECT count(*) INTO area_skills FROM curriculum_skills
  WHERE curriculum_version = 'BNCC-2018' AND stage = 'Ensino Médio'
    AND code ~ '^EM13CHS[0-9]{3}$';
  IF area_skills <> 32 THEN RAISE EXCEPTION 'Ciências Humanas: esperadas 32 habilidades, encontradas %.', area_skills; END IF;
  SELECT count(*) INTO area_skills FROM curriculum_skills
  WHERE curriculum_version = 'BNCC-2018' AND stage = 'Ensino Médio'
    AND code ~ '^EM13LGG[0-9]{3}$';
  IF area_skills <> 28 THEN RAISE EXCEPTION 'Linguagens: esperadas 28 habilidades de área, encontradas %.', area_skills; END IF;
  SELECT count(*) INTO area_skills FROM curriculum_skills
  WHERE curriculum_version = 'BNCC-2018' AND stage = 'Ensino Médio'
    AND code ~ '^EM13MAT[0-9]{3}$';
  IF area_skills <> 43 THEN RAISE EXCEPTION 'Matemática: esperadas 43 habilidades, encontradas %.', area_skills; END IF;
  SELECT count(*) INTO area_skills FROM curriculum_skills
  WHERE curriculum_version = 'BNCC-2018' AND stage = 'Ensino Médio'
    AND code ~ '^EM13CNT[0-9]{3}$';
  IF area_skills <> 26 THEN RAISE EXCEPTION 'Ciências da Natureza: esperadas 26 habilidades, encontradas %.', area_skills; END IF;

  SELECT count(*) INTO competency_links
  FROM curriculum_skills skill JOIN skill_competencies link ON link.skill_id = skill.id
  WHERE skill.curriculum_version = 'BNCC-2018' AND skill.stage = 'Ensino Médio'
    AND skill.code ~ '^EM13(CHS|LGG|MAT|CNT)[0-9]{3}$';
  IF competency_links <> 129 THEN
    RAISE EXCEPTION 'Vínculos de competências das áreas incorretos: esperados 129, encontrados %.', competency_links;
  END IF;
  SELECT count(*) INTO missing_competency_links
  FROM curriculum_skills skill
  LEFT JOIN skill_competencies link ON link.skill_id = skill.id
  WHERE skill.curriculum_version = 'BNCC-2018' AND skill.stage = 'Ensino Médio'
    AND skill.code ~ '^EM13(CHS|LGG|MAT|CNT)[0-9]{3}$'
    AND link.skill_id IS NULL;
  IF missing_competency_links <> 0 THEN
    RAISE EXCEPTION 'Há % habilidades de área sem vínculo de competência.', missing_competency_links;
  END IF;
END $$;
